package com.skillingcost;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** Values captured on the EDT; workers never read mutable panel controls. */
final class CalculationRequest
{
    final long revision;
    final List<SkillingMethod> methods;
    final String selectedId;
    final int currentXp;
    final int targetXp;
    final int currentLevel;
    final int targetLevel;
    final int batchSize;
    final boolean optional;
    final boolean sell;
    final boolean tax;
    final boolean refresh;

    CalculationRequest(long revision, List<SkillingMethod> methods, String selectedId,
        int currentXp, int targetXp, int currentLevel, int targetLevel, int batchSize,
        boolean optional, boolean sell, boolean tax, boolean refresh)
    {
        this.revision = revision;
        this.methods = Collections.unmodifiableList(new ArrayList<>(methods));
        this.selectedId = selectedId;
        this.currentXp = currentXp;
        this.targetXp = targetXp;
        this.currentLevel = currentLevel;
        this.targetLevel = targetLevel;
        this.batchSize = batchSize;
        this.optional = optional;
        this.sell = sell;
        this.tax = tax;
        this.refresh = refresh;
    }

    Set<Integer> priceIds()
    {
        Set<Integer> ids = new LinkedHashSet<>();
        if (targetXp <= currentXp) { return ids; }
        for (SkillingMethod method : methods)
        {
            ids.addAll(method.getPriceItemIds(optional, sell));
        }
        return ids;
    }
}

package com.skillingcost;

import java.util.Map;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import net.runelite.api.Skill;

interface CalculatorController
{
    void loadCurrentSkillXp(Skill skill, IntConsumer callback);
    void estimate(CalculationRequest request, Consumer<Map<String, CostResult>> success, Consumer<String> failure);
}

package com.skillingcost;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/** Ephemeral goals and preferences, independent of control applicability. */
final class CalculatorSession
{
    static final int MAX_XP = 200_000_000;
    static final class Goal
    {
        int currentXp;
        int targetXp = Experience.getXpForLevel(2);
        boolean explicitTarget;
        boolean xpLoaded;
        long xpEditRevision;
        String selectedId;
        String search = "";
        final Map<String, String> variants = new HashMap<>();

        void current(int xp, boolean manual)
        {
            currentXp = xp;
            if (manual) { xpEditRevision++; }
            if (!explicitTarget)
            {
                int level = level(xp);
                targetXp = level == 99 ? xp : Experience.getXpForLevel(level + 1);
            }
        }

        void target(int xp)
        {
            targetXp = xp;
            explicitTarget = true;
        }

        boolean applyLoaded(int xp, long editRevision)
        {
            if (xp < 0 || xpEditRevision != editRevision) { return false; }
            current(Math.min(MAX_XP, xp), false);
            xpLoaded = true;
            return true;
        }
    }

    private final Map<Skill, Goal> goals = new EnumMap<>(Skill.class);
    boolean optional = true;
    boolean sell = true;
    boolean tax = true;
    int batchSize = 28;

    Goal goal(Skill skill) { return goals.computeIfAbsent(skill, ignored -> new Goal()); }
    static int level(int xp) { return Math.min(99, Experience.getLevelForXp(xp)); }
}

package com.skillingcost;

import java.math.BigInteger;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** One pure calculation path for both comparison and detail views. */
final class CostCalculator
{
    static final class TaxSettings
    {
        final int basisPoints;
        final long capGp;
        final long exemptBelowGp;

        TaxSettings(int basisPoints, long capGp, long exemptBelowGp)
        {
            this.basisPoints = basisPoints;
            this.capGp = capGp;
            this.exemptBelowGp = exemptBelowGp;
        }

        boolean valid()
        {
            return basisPoints >= 0 && basisPoints <= 10_000 && capGp >= 0 && exemptBelowGp >= 0;
        }
    }

    private CostCalculator() { }

    static CostResult calculate(SkillingMethod method, int currentLevel, int currentXp,
        int targetLevel, int targetXp, boolean optional, boolean sell, boolean includeTax,
        int batchSize, PriceSnapshot snapshot, TaxSettings tax, Instant now)
    {
        int xpNeeded = Math.max(0, targetXp - currentXp);
        long actions = 0;
        long inputCost = 0;
        long outputGross = 0;
        long totalTax = 0;
        long net = 0;
        List<String> requiredLines = new ArrayList<>();
        List<String> optionalLines = new ArrayList<>();
        List<String> outputLines = new ArrayList<>();
        Context context = new Context(snapshot, now);
        CostResult.State state = CostResult.State.AVAILABLE;
        try
        {
            actions = method.actionsFor(xpNeeded);
            if (includeTax && sell && method.hasSellableOutputs() && !tax.valid())
            {
                state = CostResult.State.INVALID_SETTINGS;
                context.notices.add("Invalid GE tax settings. Check the plugin configuration.");
            }
            else
            {
                for (ItemQuantity input : method.getRequiredInputs())
                {
                    inputCost = Math.addExact(inputCost, inputLine(input, actions, batchSize, context, requiredLines));
                }
                if (optional)
                {
                    for (ItemQuantity input : method.getOptionalInputs())
                    {
                        inputCost = Math.addExact(inputCost, inputLine(input, actions, batchSize, context, optionalLines));
                    }
                }
                int multiplier = method.outputMultiplier(currentLevel);
                for (ItemQuantity output : method.getOutputs())
                {
                    long quantity = output.total(actions, batchSize, multiplier, true);
                    if (!sell || !output.isGePriced() || quantity == 0)
                    {
                        outputLines.add(String.format("%,d × %s", quantity, output.getName())
                            + (output.isGePriced() ? "\nNot sold." : "\nUntradeable; not GE-priced."));
                        continue;
                    }
                    WikiPrice.Quote quote = context.quote(output, false);
                    if (quote == null)
                    {
                        outputLines.add(String.format("%,d × %s\nSell quote unavailable.", quantity, output.getName()));
                        continue;
                    }
                    long total = Math.multiplyExact(quantity, quote.gp);
                    outputGross = Math.addExact(outputGross, total);
                    totalTax = Math.addExact(totalTax, includeTax && !output.isTaxExempt()
                        ? geTax(quote.gp, quantity, tax) : 0);
                    outputLines.add(Formats.itemLine(output.getName(), quantity, quote.gp, total)
                        + context.quoteNote(output, quote));
                }
                if (context.missing)
                {
                    state = CostResult.State.MISSING_QUOTES;
                }
                else
                {
                    net = Math.subtractExact(Math.subtractExact(outputGross, totalTax), inputCost);
                }
                if (method.hasLevelDependentOutput())
                {
                    context.notices.add("Output multiplier: " + multiplier + "× at starting level " + currentLevel
                        + "; held constant throughout this estimate.");
                }
            }
        }
        catch (ArithmeticException e)
        {
            state = CostResult.State.OUT_OF_RANGE;
            context.notices.add("Estimate exceeds the supported 64-bit quantity or GP range.");
        }
        return new CostResult(method, currentLevel, currentXp, targetLevel, targetXp, xpNeeded,
            actions, inputCost, outputGross, totalTax, net, requiredLines, optionalLines, outputLines,
            optional, sell, context.oldest, snapshot.fetchedAt, state, new ArrayList<>(context.notices));
    }


    static long geTax(long price, long quantity, TaxSettings tax)
    {
        if (!tax.valid() || price < 0 || quantity < 0)
        {
            throw new IllegalArgumentException("Invalid tax inputs");
        }
        if (price < tax.exemptBelowGp) { return 0; }
        long perItem = BigInteger.valueOf(price).multiply(BigInteger.valueOf(tax.basisPoints))
            .divide(BigInteger.valueOf(10_000)).min(BigInteger.valueOf(tax.capGp)).longValueExact();
        return Math.multiplyExact(perItem, quantity);
    }

    private static long inputLine(ItemQuantity item, long actions, int batchSize, Context context, List<String> lines)
    {
        long quantity = item.total(actions, batchSize, 1, false);
        if (quantity == 0)
        {
            lines.add("0 × " + item.getName());
            return 0;
        }
        if (item.getPricing() == ItemQuantity.Pricing.UNTRADEABLE)
        {
            lines.add(String.format("%,d × %s\nUntradeable; collect these supplies. Not GE-priced.", quantity, item.getName()));
            return 0;
        }
        if (item.hasFixedUnitPrice())
        {
            long total = Math.multiplyExact(quantity, item.getFixedUnitPrice());
            lines.add(Formats.itemLine(item.getName(), quantity, item.getFixedUnitPrice(), total) + "\nFixed fee.");
            return total;
        }
        WikiPrice.Quote quote = context.quote(item, true);
        if (quote == null)
        {
            lines.add(String.format("%,d × %s\nBuy quote unavailable.", quantity, item.getName()));
            return 0;
        }
        long total = Math.multiplyExact(quantity, quote.gp);
        lines.add(Formats.itemLine(item.getName(), quantity, quote.gp, total) + context.quoteNote(item, quote));
        return total;
    }

    private static final class Context
    {
        final PriceSnapshot snapshot;
        final Instant now;
        final Set<String> notices = new LinkedHashSet<>();
        boolean missing;
        long oldest;

        Context(PriceSnapshot snapshot, Instant now)
        {
            this.snapshot = snapshot;
            this.now = now;
        }

        WikiPrice.Quote quote(ItemQuantity item, boolean buy)
        {
            WikiPrice price = snapshot.prices.get(item.getItemId());
            WikiPrice.Quote quote = price == null ? null : buy ? price.buyQuote() : price.sellQuote();
            if (quote == null)
            {
                missing = true;
                notices.add("Quote unavailable: " + item.getName());
            }
            return quote;
        }

        String quoteNote(ItemQuantity item, WikiPrice.Quote quote)
        {
            String note = "\n" + quote.side + (quote.fallback ? " (fallback)" : "");
            if (quote.fallback)
            {
                notices.add("Opposite-side quote used: " + item.getName());
            }
            if (quote.timestamp == null || quote.timestamp > now.getEpochSecond())
            {
                notices.add("Quote age unknown: " + item.getName());
                return note + "; age unknown.";
            }
            oldest = oldest == 0 ? quote.timestamp : Math.min(oldest, quote.timestamp);
            long age = now.getEpochSecond() - quote.timestamp;
            if (age > 600)
            {
                notices.add("Quote older than ten minutes: " + item.getName());
                note += "; stale";
            }
            return note + "; " + Instant.ofEpochSecond(quote.timestamp) + ".";
        }
    }
}

package com.skillingcost;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class CostResult
{
    enum State { AVAILABLE, MISSING_QUOTES, OUT_OF_RANGE, INVALID_SETTINGS }

    private final SkillingMethod method;
    private final int currentLevel;
    private final int currentXp;
    private final int targetLevel;
    private final int targetXp;
    private final int xpNeeded;
    private final long actionsNeeded;
    private final long inputCost;
    private final long outputGross;
    private final long tax;
    private final long net;
    private final List<String> requiredInputLines;
    private final List<String> optionalInputLines;
    private final List<String> outputLines;
    private final boolean includeOptionalInputs;
    private final boolean sellOutputs;
    private final long oldestPriceTimestamp;
    private final Instant snapshotTime;
    private final State state;
    private final List<String> notices;

    CostResult(SkillingMethod method, int currentLevel, int currentXp, int targetLevel, int targetXp,
        int xpNeeded, long actionsNeeded, long inputCost, long outputGross, long tax, long net,
        List<String> requiredLines, List<String> optionalLines, List<String> outputLines,
        boolean optional, boolean sell, long oldestTimestamp, Instant snapshotTime, State state, List<String> notices)
    {
        this.method = method;
        this.currentLevel = currentLevel;
        this.currentXp = currentXp;
        this.targetLevel = targetLevel;
        this.targetXp = targetXp;
        this.xpNeeded = xpNeeded;
        this.actionsNeeded = actionsNeeded;
        this.inputCost = inputCost;
        this.outputGross = outputGross;
        this.tax = tax;
        this.net = net;
        this.requiredInputLines = immutable(requiredLines);
        this.optionalInputLines = immutable(optionalLines);
        this.outputLines = immutable(outputLines);
        this.includeOptionalInputs = optional;
        this.sellOutputs = sell;
        this.oldestPriceTimestamp = oldestTimestamp;
        this.snapshotTime = snapshotTime;
        this.state = state;
        this.notices = immutable(notices);
    }

    private static List<String> immutable(List<String> values)
    {
        return Collections.unmodifiableList(new ArrayList<>(values));
    }

    SkillingMethod getMethod() { return method; }
    int getCurrentLevel() { return currentLevel; }
    int getCurrentXp() { return currentXp; }
    int getTargetLevel() { return targetLevel; }
    int getTargetXp() { return targetXp; }
    int getXpNeeded() { return xpNeeded; }
    long getActionsNeeded() { return actionsNeeded; }
    long getInputCost() { return inputCost; }
    long getOutputGross() { return outputGross; }
    long getTax() { return tax; }
    long getNet() { return net; }
    List<String> getRequiredInputLines() { return requiredInputLines; }
    List<String> getOptionalInputLines() { return optionalInputLines; }
    List<String> getOutputLines() { return outputLines; }
    boolean isIncludeOptionalInputs() { return includeOptionalInputs; }
    boolean isSellOutputs() { return sellOutputs; }
    long getOldestPriceTimestamp() { return oldestPriceTimestamp; }
    Instant getSnapshotTime() { return snapshotTime; }
    State getState() { return state; }
    boolean isAvailable() { return state == State.AVAILABLE; }
    List<String> getNotices() { return notices; }
}

package com.skillingcost;

import javax.swing.Timer;

interface EstimateScheduler
{
    void restart();
    void stop();

    static EstimateScheduler swing(Runnable action)
    {
        Timer timer = new Timer(250, event -> action.run());
        timer.setRepeats(false);
        return new EstimateScheduler()
        {
            public void restart() { timer.restart(); }
            public void stop() { timer.stop(); }
        };
    }
}

package com.skillingcost;

import net.runelite.api.Skill;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Locale;

/** Small text-formatting helpers shared by the plugin and panel. */
final class Formats
{
    private Formats()
    {
    }

    /** Formats a gp amount with thousands separators, e.g. {@code -12,345 gp}. */
    static String gp(long value)
    {
        return String.format(Locale.US, "%,d gp", value);
    }

    /** Compact gp for narrow UI spots, e.g. {@code -82.3M gp}, {@code 15.2K gp}, {@code 950 gp}. */
    static String gpCompact(long value)
    {
        String sign = value < 0 ? "-" : "";
        double abs = Math.abs((double) value);
        if (abs >= 1_000_000_000_000L)
        {
            return sign + String.format(Locale.US, "%.2fT gp", abs / 1_000_000_000_000.0);
        }
        if (abs >= 1_000_000_000L)
        {
            return sign + String.format(Locale.US, "%.2fB gp", abs / 1_000_000_000.0);
        }
        if (abs >= 1_000_000L)
        {
            return sign + String.format(Locale.US, "%.1fM gp", abs / 1_000_000.0);
        }
        if (abs >= 10_000L)
        {
            return sign + String.format(Locale.US, "%.0fK gp", abs / 1_000.0);
        }
        return gp(value);
    }

    static String gpPerXp(long value, int xp)
    {
        if (xp <= 0) { throw new IllegalArgumentException("XP must be positive"); }
        BigDecimal ratio = BigDecimal.valueOf(value).divide(BigDecimal.valueOf(xp), 2, RoundingMode.HALF_UP);
        return ratio.abs().compareTo(BigDecimal.valueOf(10_000)) >= 0
            ? gpCompact(ratio.longValue()) : String.format(Locale.US, "%,.2f", ratio);
    }

    /** {@code Skill.RUNECRAFT} -&gt; {@code "Runecraft"}. */
    static String skillName(Skill skill)
    {
        String text = skill.name().toLowerCase(Locale.ROOT).replace('_', ' ');
        StringBuilder out = new StringBuilder();
        boolean nextUpper = true;
        for (int i = 0; i < text.length(); i++)
        {
            char c = text.charAt(i);
            if (nextUpper && Character.isLetter(c))
            {
                out.append(Character.toUpperCase(c));
                nextUpper = false;
            }
            else
            {
                out.append(c);
            }
            if (c == ' ')
            {
                nextUpper = true;
            }
        }
        return out.toString();
    }

    /** Three display lines for one priced item: quantity x name, unit price, line total. */
    static String itemLine(String name, long quantity, long unitPrice, long total)
    {
        return String.format("%,d × %s", quantity, name)
            + "\n" + String.format("%,d gp each", unitPrice)
            + "\n" + gp(total) + " total";
    }
}

package com.skillingcost;

import java.math.BigDecimal;
import java.math.RoundingMode;

/** Explicit pricing and exact consumption units for one resource. */
final class ItemQuantity
{
    enum Pricing { GE, FIXED_GP, UNTRADEABLE }

    private final int itemId;
    private final String name;
    private final BigDecimal quantityPerAction;
    private final Pricing pricing;
    private final long fixedUnitPrice;
    private final int unitsPerItem;
    private final boolean perBatch;
    private final boolean taxExempt;

    ItemQuantity(int itemId, String name, double quantity)
    {
        this(itemId, name, BigDecimal.valueOf(quantity), Pricing.GE, 0, 1, false, false);
    }

    ItemQuantity(int itemId, String name, double quantity, long fixedPrice)
    {
        this(itemId, name, BigDecimal.valueOf(quantity), Pricing.FIXED_GP, fixedPrice, 1, false, false);
    }

    ItemQuantity(int itemId, String name, BigDecimal quantity, Pricing pricing, long fixedPrice,
        int unitsPerItem, boolean perBatch, boolean taxExempt)
    {
        if (name == null || name.trim().isEmpty() || quantity == null || quantity.signum() < 0
            || pricing == null || unitsPerItem < 1 || fixedPrice < 0
            || (pricing != Pricing.FIXED_GP && itemId <= 0))
        {
            throw new IllegalArgumentException("Invalid resource: " + name);
        }
        this.itemId = itemId;
        this.name = name;
        this.quantityPerAction = quantity;
        this.pricing = pricing;
        this.fixedUnitPrice = fixedPrice;
        this.unitsPerItem = unitsPerItem;
        this.perBatch = perBatch;
        this.taxExempt = taxExempt;
    }

    int getItemId() { return itemId; }
    String getName() { return name; }
    BigDecimal getQuantityPerAction() { return quantityPerAction; }
    Pricing getPricing() { return pricing; }
    boolean isGePriced() { return pricing == Pricing.GE; }
    boolean hasFixedUnitPrice() { return pricing == Pricing.FIXED_GP; }
    long getFixedUnitPrice() { return fixedUnitPrice; }
    boolean isTaxExempt() { return taxExempt; }
    boolean isPerBatch() { return perBatch; }

    long total(long actions, int batchSize, int multiplier, boolean output)
    {
        if (actions < 0 || batchSize < 1 || multiplier < 1)
        {
            throw new IllegalArgumentException("Invalid action or batch count");
        }
        long units = perBatch ? ceilDivide(actions, batchSize) : actions;
        return quantityPerAction.multiply(BigDecimal.valueOf(units))
            .multiply(BigDecimal.valueOf(output ? multiplier : 1))
            .divide(BigDecimal.valueOf(unitsPerItem), 0, output ? RoundingMode.FLOOR : RoundingMode.CEILING)
            .longValueExact();
    }

    private static long ceilDivide(long value, int divisor)
    {
        return value / divisor + (value % divisor == 0 ? 0 : 1);
    }
}

package com.skillingcost;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** One row ranks its selected eligible variant. */
final class MethodListEntry
{
    private final String displayName;
    private final List<SkillingMethod> variants;
    private int selectedVariantIndex;

    private MethodListEntry(String name, List<SkillingMethod> variants)
    {
        this.displayName = name;
        this.variants = Collections.unmodifiableList(new ArrayList<>(variants));
    }

    static List<MethodListEntry> build(List<SkillingMethod> methods)
    {
        Map<String, List<SkillingMethod>> groups = new LinkedHashMap<>();
        for (SkillingMethod method : methods)
        {
            String key = method.getGroupName() == null ? method.getId() : method.getGroupName();
            groups.computeIfAbsent(key, ignored -> new ArrayList<>()).add(method);
        }
        List<MethodListEntry> result = new ArrayList<>();
        for (List<SkillingMethod> group : groups.values())
        {
            SkillingMethod first = group.get(0);
            result.add(new MethodListEntry(first.getGroupName() == null ? first.getName() : first.getGroupName(), group));
        }
        return result;
    }

    MethodListEntry filtered(String search, int level, boolean hideLocked, String preferredId)
    {
        String query = search.trim().toLowerCase(Locale.ROOT);
        boolean groupMatch = displayName.toLowerCase(Locale.ROOT).contains(query);
        List<SkillingMethod> eligible = new ArrayList<>();
        for (SkillingMethod method : variants)
        {
            boolean match = groupMatch || method.getName().toLowerCase(Locale.ROOT).contains(query)
                || (method.getVariantName() != null && method.getVariantName().toLowerCase(Locale.ROOT).contains(query));
            if (match && (!hideLocked || method.getRequiredLevel() <= level)) { eligible.add(method); }
        }
        if (eligible.isEmpty()) { return null; }
        MethodListEntry result = new MethodListEntry(displayName, eligible);
        for (int i = 0; i < eligible.size(); i++)
        {
            if (eligible.get(i).getId().equals(preferredId)) { result.selectedVariantIndex = i; }
        }
        return result;
    }

    String getDisplayName() { return displayName; }
    boolean hasVariants() { return variants.size() > 1; }
    List<SkillingMethod> getVariants() { return variants; }
    SkillingMethod getSelected() { return variants.get(selectedVariantIndex); }
    int getSelectedVariantIndex() { return selectedVariantIndex; }
    void setSelectedVariantIndex(int index)
    {
        if (index >= 0 && index < variants.size()) { selectedVariantIndex = index; }
    }
    @Override
    public String toString() { return displayName; }
}

package com.skillingcost;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

/** Loads the bundled catalog and expands Prayer offerings. Preload off the client thread. */
@Singleton
final class MethodRepository
{
    private static final String RESOURCE = "/methods.json";
    private static final String PRAYER_SOURCE = "https://oldschool.runescape.wiki/w/Prayer";
    private static final EnumSet<Skill> SUPPORTED = EnumSet.of(Skill.SMITHING, Skill.HERBLORE, Skill.FISHING,
        Skill.COOKING, Skill.PRAYER, Skill.CRAFTING, Skill.FIREMAKING, Skill.MAGIC, Skill.FLETCHING,
        Skill.RUNECRAFT, Skill.CONSTRUCTION);
    private final Gson gson;
    private List<Skill> supportedSkills;
    private Map<Skill, List<SkillingMethod>> methodsBySkill;

    @Inject
    MethodRepository(Gson gson) { this.gson = gson; }

    synchronized List<Skill> getSupportedSkills() { load(); return supportedSkills; }
    synchronized Map<Skill, List<SkillingMethod>> getMethodsBySkill() { load(); return methodsBySkill; }

    private void load()
    {
        if (methodsBySkill != null) { return; }
        try (InputStream stream = MethodRepository.class.getResourceAsStream(RESOURCE))
        {
            if (stream == null) { throw new IllegalStateException("Missing bundled " + RESOURCE); }
            read(new InputStreamReader(stream, StandardCharsets.UTF_8));
        }
        catch (Exception exception)
        {
            throw new IllegalStateException("Invalid bundled catalog: " + exception.getMessage(), exception);
        }
    }

    synchronized void read(Reader reader)
    {
        RootJson root = gson.fromJson(reader, RootJson.class);
        if (root == null || root.skills == null || root.methods == null || root.prayer == null)
        {
            throw new IllegalArgumentException("Missing skills, methods, or Prayer table");
        }
        List<Skill> skills = new ArrayList<>();
        Map<Skill, List<SkillingMethod>> map = new LinkedHashMap<>();
        for (String name : root.skills)
        {
            Skill skill = Skill.valueOf(name);
            if (!SUPPORTED.contains(skill) || map.containsKey(skill))
            {
                throw new IllegalArgumentException("Invalid or duplicate skill: " + name);
            }
            skills.add(skill);
            map.put(skill, new ArrayList<>());
        }
        if (!map.keySet().equals(SUPPORTED))
        {
            throw new IllegalArgumentException("Catalog must contain the 11 supported skills");
        }
        Set<String> identities = new HashSet<>();
        for (MethodJson recipe : root.methods)
        {
            Skill skill = Skill.valueOf(recipe.skill);
            if (!map.containsKey(skill)) { throw new IllegalArgumentException("Unsupported skill: " + recipe.skill); }
            SkillingMethod method = new SkillingMethod(skill, recipe.key, recipe.name, recipe.group, recipe.variant,
                recipe.level, recipe.xp, toItems(recipe.inputs), toItems(recipe.optional),
                toItems(recipe.outputs), recipe.action, recipe.source, recipe.assumptions, recipe.outputLevels);
            add(map, method, identities);
        }
        for (SkillingMethod method : expandPrayer(root.prayer)) { add(map, method, identities); }
        for (Map.Entry<Skill, List<SkillingMethod>> entry : map.entrySet())
        {
            entry.setValue(Collections.unmodifiableList(entry.getValue()));
        }
        supportedSkills = Collections.unmodifiableList(skills);
        methodsBySkill = Collections.unmodifiableMap(map);
    }

    private static void add(Map<Skill, List<SkillingMethod>> map, SkillingMethod method, Set<String> ids)
    {
        if (!ids.add(method.getId())) { throw new IllegalArgumentException("Duplicate recipe: " + method.getId()); }
        map.get(method.getSkill()).add(method);
    }

    private static List<SkillingMethod> expandPrayer(PrayerJson prayer)
    {
        if (prayer.bones == null || prayer.ashes == null || prayer.libationMinLevel < 1
            || prayer.libationMinLevel > 99 || prayer.libationFeeGp < 0)
        {
            throw new IllegalArgumentException("Invalid Prayer table");
        }
        List<SkillingMethod> methods = new ArrayList<>();
        for (BoneJson bone : prayer.bones)
        {
            if (!Double.isFinite(bone.buryXp) || bone.buryXp <= 0 || bone.shards <= 0)
            {
                throw new IllegalArgumentException("Invalid bone: " + bone.name);
            }
            methods.add(boneMethod("bury", "Bury", bone, bone.level, bone.buryXp,
                items(ref(bone, BigDecimal.ONE)), "One bone buried."));
            methods.add(boneMethod("gilded", "Gilded altar (both burners lit)", bone, bone.level, bone.buryXp * 3.5,
                items(ref(bone, BigDecimal.ONE)), "Both burners lit. Burner and travel costs excluded."));
            methods.add(boneMethod("chaos", "Chaos altar (avg. 50% bone save)", bone, bone.level, bone.buryXp * 7,
                items(ref(bone, BigDecimal.ONE)), "Long-run average XP per consumed bone; actual bone saves vary. Travel and risk excluded."));
            methods.add(boneMethod("ecto", "Ectofuntus", bone, bone.level, bone.buryXp * 4,
                items(ref(bone, BigDecimal.ONE), ref(prayer.bucketOfSlime, BigDecimal.ONE)),
                "Collected slime required. Empty pots, returned buckets, travel, and grinding costs excluded."));
            for (boolean sunfire : new boolean[]{false, true})
            {
                List<ItemQuantity> inputs = items(ref(bone, BigDecimal.ONE),
                    new ItemQuantity(-1, "Virilis unnoting fee", 1, prayer.libationFeeGp),
                    ref(prayer.jugOfWine, BigDecimal.valueOf(bone.shards).divide(BigDecimal.valueOf(400))));
                if (sunfire)
                {
                    inputs.add(ref(prayer.sunfireSplinters,
                        BigDecimal.valueOf(bone.shards).divide(BigDecimal.valueOf(200))));
                }
                methods.add(boneMethod(sunfire ? "sunfire" : "blessed",
                    sunfire ? "Libation bowl (sunfire wine)" : "Libation bowl (blessed wine)", bone,
                    Math.max(prayer.libationMinLevel, bone.level), bone.shards * (sunfire ? 6.0 : 5.0), inputs,
                    "One action processes all shards from one bone. Wine/splinters rounded over the whole plan. No Zealot shard saves; collection and travel excluded."));
            }
        }
        for (AshJson ash : prayer.ashes)
        {
            methods.add(new SkillingMethod(Skill.PRAYER, "prayer:scatter:" + ash.resource,
                "Scatter " + ash.name, "Scatter ashes", ash.name, ash.level, ash.scatterXp,
                items(ref(ash, BigDecimal.ONE)), Collections.emptyList(), Collections.emptyList(),
                "ash scattered", PRAYER_SOURCE, "One ash scattered.", new int[0]));
        }
        return methods;
    }

    private static SkillingMethod boneMethod(String key, String group, BoneJson bone, int level, double xp,
        List<ItemQuantity> inputs, String assumptions)
    {
        return new SkillingMethod(Skill.PRAYER, "prayer:" + key + ":" + bone.resource,
            group + " - " + bone.name, group, bone.name, level, xp, inputs,
            Collections.emptyList(), Collections.emptyList(), "bone processed", PRAYER_SOURCE, assumptions, new int[0]);
    }

    private static ItemQuantity ref(ItemRefJson item, BigDecimal quantity)
    {
        if (item == null) { throw new IllegalArgumentException("Missing Prayer supply"); }
        ItemQuantity.Pricing pricing = pricing(item.pricing);
        if (pricing == ItemQuantity.Pricing.FIXED_GP) { throw new IllegalArgumentException("Prayer item is a fee"); }
        return new ItemQuantity(ResourceRegistry.require(item.resource), item.name, quantity, pricing,
            0, 1, false, false);
    }

    private static ItemQuantity.Pricing pricing(String value)
    {
        if (value == null) { throw new IllegalArgumentException("Missing pricing mode"); }
        return ItemQuantity.Pricing.valueOf(value);
    }

    private static List<ItemQuantity> items(ItemQuantity... values)
    {
        List<ItemQuantity> list = new ArrayList<>();
        Collections.addAll(list, values);
        return list;
    }

    private static List<ItemQuantity> toItems(List<ItemJson> values)
    {
        List<ItemQuantity> list = new ArrayList<>();
        if (values == null) { return list; }
        for (ItemJson item : values)
        {
            ItemQuantity.Pricing mode = pricing(item.pricing);
            if ((mode == ItemQuantity.Pricing.FIXED_GP) != (item.fixedPrice != null)
                || (mode == ItemQuantity.Pricing.FIXED_GP && item.resource != null))
            {
                throw new IllegalArgumentException("Inconsistent pricing: " + item.name);
            }
            int id = mode == ItemQuantity.Pricing.FIXED_GP ? -1 : ResourceRegistry.require(item.resource);
            list.add(new ItemQuantity(id, item.name, item.qty, mode,
                item.fixedPrice == null ? 0 : item.fixedPrice,
                item.unitsPerItem == null ? 1 : item.unitsPerItem, item.perBatch, item.taxExempt));
        }
        return list;
    }

    private static final class RootJson
    {
        List<String> skills;
        List<MethodJson> methods;
        PrayerJson prayer;
    }

    private static final class MethodJson
    {
        String key, skill, name, group, variant, action, source, assumptions;
        int level;
        double xp;
        int[] outputLevels;
        List<ItemJson> inputs, optional, outputs;
    }

    private static final class ItemJson
    {
        String resource, name, pricing;
        BigDecimal qty;
        Long fixedPrice;
        Integer unitsPerItem;
        boolean perBatch, taxExempt;
    }

    private static class ItemRefJson
    {
        String resource, name, pricing;
    }

    private static final class BoneJson extends ItemRefJson
    {
        int level, shards;
        double buryXp;
    }

    private static final class AshJson extends ItemRefJson
    {
        int level;
        double scatterXp;
    }

    private static final class PrayerJson
    {
        int libationMinLevel;
        long libationFeeGp;
        ItemRefJson jugOfWine, sunfireSplinters, bucketOfSlime;
        List<BoneJson> bones;
        List<AshJson> ashes;
    }
}

package com.skillingcost;

import com.google.gson.Gson;
import java.io.IOException;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
@Singleton
final class PriceService
{
    private static final String LATEST_URL = "https://prices.runescape.wiki/api/v2/osrs/latest";
    private static final Duration CACHE_DURATION = Duration.ofSeconds(60);

    private final Call.Factory calls;
    private final Gson gson;
    private final SkillingCostConfig config;
    private final Clock clock;
    private final Object lock = new Object();
    private final List<WaitingConsumer> waiting = new ArrayList<>();

    private PriceSnapshot cache;
    private Call activeCall;
    private long generation;

    @Inject
    PriceService(OkHttpClient client, Gson gson, SkillingCostConfig config)
    {
        this(client, gson, config, Clock.systemUTC());
    }

    PriceService(Call.Factory calls, Gson gson, SkillingCostConfig config, Clock clock)
    {
        this.calls = calls;
        this.gson = gson;
        this.config = config;
        this.clock = clock;
    }

    void getLatestSnapshot(Set<Integer> ids, boolean refresh, Consumer<PriceSnapshot> success, Consumer<String> error)
    {
        if (ids.isEmpty())
        {
            success.accept(new PriceSnapshot(Collections.emptyMap(), Instant.EPOCH));
            return;
        }
        if (!config.enableWikiPrices())
        {
            error.accept("Enable Wiki prices in plugin config to price GE resources.");
            return;
        }
        WaitingConsumer consumer = new WaitingConsumer(ids, success, error);
        PriceSnapshot cached = null;
        Call started = null;
        long requestGeneration;
        synchronized (lock)
        {
            requestGeneration = generation;
            Duration age = cache == null ? CACHE_DURATION : Duration.between(cache.fetchedAt, clock.instant());
            if (!refresh && cache != null && !age.isNegative() && age.compareTo(CACHE_DURATION) < 0)
            {
                cached = subset(cache, ids);
            }
            else
            {
                waiting.add(consumer);
                if (activeCall == null)
                {
                    try
                    {
                        activeCall = calls.newCall(new Request.Builder().url(LATEST_URL)
                            .header("User-Agent", wikiUserAgent()).build());
                        started = activeCall;
                    }
                    catch (RuntimeException e)
                    {
                        waiting.remove(consumer);
                        log.debug("Cannot prepare price request", e);
                    }
                }
            }
        }
        if (cached != null)
        {
            if (isCurrent(requestGeneration)) { success.accept(cached); }
            return;
        }
        if (started == null)
        {
            synchronized (lock)
            {
                if (activeCall != null || generation != requestGeneration) { return; }
            }
            error.accept("Unable to prepare price request. Check the Wiki User-Agent setting.");
            return;
        }
        final long token = requestGeneration;
        final Call call = started;
        Callback callback = new Callback()
        {
            @Override
            public void onFailure(Call failed, IOException exception)
            {
                log.debug("Price acquisition failed", exception);
                complete(call, token, null, "Could not reach Wiki prices. Try refreshing.");
            }

            @Override
            public void onResponse(Call responded, Response response)
            {
                PriceSnapshot snapshot = null;
                String failure = null;
                try (Response ignored = response)
                {
                    if (!response.isSuccessful())
                    {
                        failure = "Wiki price request failed (HTTP " + response.code() + ").";
                    }
                    else
                    {
                        ResponseBody body = response.body();
                        if (body == null)
                        {
                            failure = "Wiki prices returned an empty response.";
                        }
                        else
                        {
                            snapshot = new PriceSnapshot(WikiLatestResponse.parse(gson, body.string()), clock.instant());
                        }
                    }
                }
                catch (IOException | RuntimeException exception)
                {
                    log.debug("Cannot read Wiki price response", exception);
                    failure = "Wiki prices returned an unreadable response. Try refreshing.";
                }
                complete(call, token, snapshot, failure);
            }
        };
        try
        {
            call.enqueue(callback);
        }
        catch (RuntimeException exception)
        {
            log.debug("Cannot queue price request", exception);
            complete(call, token, null, "Unable to start the Wiki price request. Try refreshing.");
        }
    }

    private void complete(Call call, long token, PriceSnapshot snapshot, String error)
    {
        List<WaitingConsumer> consumers;
        synchronized (lock)
        {
            if (activeCall != call || generation != token) { return; }
            activeCall = null;
            consumers = new ArrayList<>(waiting);
            waiting.clear();
            if (snapshot != null) { cache = snapshot; }
        }
        for (WaitingConsumer consumer : consumers)
        {
            if (!isCurrent(token)) { return; }
            try
            {
                if (snapshot != null) { consumer.success.accept(subset(snapshot, consumer.ids)); }
                else { consumer.error.accept(error); }
            }
            catch (RuntimeException exception)
            {
                log.debug("Price consumer failed", exception);
            }
        }
    }

    void cancel()
    {
        Call cancel;
        synchronized (lock)
        {
            generation++;
            cancel = activeCall;
            activeCall = null;
            waiting.clear();
            cache = null;
        }
        if (cancel != null) { cancel.cancel(); }
    }

    private boolean isCurrent(long token)
    {
        synchronized (lock)
        {
            return generation == token && config.enableWikiPrices();
        }
    }

    private static PriceSnapshot subset(PriceSnapshot snapshot, Set<Integer> ids)
    {
        Map<Integer, WikiPrice> prices = new HashMap<>();
        for (Integer id : ids)
        {
            WikiPrice quote = snapshot.prices.get(id);
            if (quote != null) { prices.put(id, quote); }
        }
        return new PriceSnapshot(prices, snapshot.fetchedAt);
    }

    private String wikiUserAgent()
    {
        String agent = config.wikiUserAgent();
        if (agent == null || agent.trim().isEmpty()
            || "skilling-cost-calculator RuneLite plugin".equals(agent.trim()))
        {
            return SkillingCostConfig.DEFAULT_WIKI_USER_AGENT;
        }
        return agent.trim();
    }

    private static final class WaitingConsumer
    {
        final Set<Integer> ids;
        final Consumer<PriceSnapshot> success;
        final Consumer<String> error;

        WaitingConsumer(Set<Integer> ids, Consumer<PriceSnapshot> success, Consumer<String> error)
        {
            this.ids = Collections.unmodifiableSet(new java.util.LinkedHashSet<>(ids));
            this.success = success;
            this.error = error;
        }
    }
}

package com.skillingcost;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

final class PriceSnapshot
{
    final Map<Integer, WikiPrice> prices;
    final Instant fetchedAt;

    PriceSnapshot(Map<Integer, WikiPrice> prices, Instant fetchedAt)
    {
        this.prices = Collections.unmodifiableMap(new HashMap<>(prices));
        this.fetchedAt = fetchedAt;
    }
}

