    enum MethodSort
    {
        LEAST_ACTIONS("Least actions"), MOST_PROFITABLE("Most profitable");
        private final String label;
        MethodSort(String label) { this.label = label; }
        @Override public String toString() { return label; }
    }

    private final CalculatorController controller;
    private final Map<Skill, List<SkillingMethod>> methods;
    final CalculatorSession session = new CalculatorSession();
    final JComboBox<Skill> skillSelect;
    final JComboBox<MethodSort> sortSelect = new JComboBox<>(MethodSort.values());
    final JTextField search = new JTextField();
    final JCheckBox hideLocked = new JCheckBox("Hide locked methods");
    final JSpinner currentLevel = spinner(1, 1, 99);
    final JSpinner currentXp = spinner(0, 0, CalculatorSession.MAX_XP);
    final JSpinner targetLevel = spinner(2, 1, 99);
    final JSpinner targetXp = spinner(Experience.getXpForLevel(2), 0, CalculatorSession.MAX_XP);
    final JSpinner batchSize = spinner(28, 1, 1000);
    final JCheckBox optional = new JCheckBox("<html>Include optional<br>consumables</html>", true);
    final JCheckBox sell = new JCheckBox("Sell outputs", true);
    final JCheckBox tax = new JCheckBox("Include GE tax", true);
    final JButton loadXp = new JButton("Load current XP");
    final JButton refresh = new JButton("Refresh prices");
    static final class MethodListModel extends DefaultListModel<MethodListEntry>
    {
        void widthChanged()
        {
            if (!isEmpty()) { fireContentsChanged(this, 0, size() - 1); }
        }
    }

    final MethodListModel rows = new MethodListModel();
    final JList<MethodListEntry> list = new JList<MethodListEntry>(rows)
    {
        @Override
        public boolean getScrollableTracksViewportWidth() { return true; }

        @Override
        public void setBounds(int x, int y, int width, int height)
        {
            boolean widthChanged = width != getWidth();
            super.setBounds(x, y, width, height);
            // Wrapped cell heights must be measured again after the viewport width changes.
            if (widthChanged) { rows.widthChanged(); }
        }
    };
    private final JPanel rowRenderer = new JPanel(new BorderLayout(0, 4))
    {
        @Override
        public Dimension getPreferredSize()
        {
            Dimension size = super.getPreferredSize();
            size.height = Math.max(64, size.height);
            return size;
        }
    };
    private final javax.swing.JTextArea rowName = rowText();
    private final javax.swing.JTextArea rowDescription = rowText();
    final JComboBox<SkillingMethod> variants = new JComboBox<>();
    final ResultRenderer renderer = new ResultRenderer();
    private final JLabel empty = new JLabel("No matching methods.");
    private final JLabel ranking = new JLabel("<html>Rows rank their selected<br>variant.</html>");
    private final JPanel variantRow;
    private final JPanel batchRow;
    private final EstimateScheduler scheduler;
    private Map<String, CostResult> estimates = Collections.emptyMap();
    private Skill skill;
    private boolean syncing;
    private boolean disposed;
    private boolean validInputs = true;
    private long revision;
    private long xpLoadRevision;

    SkillingCostPanel(CalculatorController controller, MethodRepository repository)
    {
        this(controller, repository, EstimateScheduler::swing);
    }

    SkillingCostPanel(CalculatorController controller, MethodRepository repository,
        Function<Runnable, EstimateScheduler> scheduling)
    {
        super(false);
        this.controller = controller;
        methods = repository.getMethodsBySkill();
        skillSelect = new JComboBox<>(repository.getSupportedSkills().toArray(new Skill[0]));
        javax.swing.DefaultListCellRenderer skillsRenderer = new javax.swing.DefaultListCellRenderer();
        skillSelect.setRenderer((view, value, index, selected, focus) ->
            skillsRenderer.getListCellRendererComponent(view, value == null ? "" : Formats.skillName(value), index, selected, focus));
        javax.swing.DefaultListCellRenderer variantsRenderer = new javax.swing.DefaultListCellRenderer();
        variants.setRenderer((view, value, index, selected, focus) -> {
            String name = value == null ? "" : value.getVariantName() == null ? value.getName() : value.getVariantName();
            Component component = variantsRenderer.getListCellRendererComponent(view, name, index, selected, focus);
            ((JLabel) component).setToolTipText(value == null ? null : value.getName());
            return component;
        });
        scheduler = scheduling.apply(() -> estimate(false));
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        JPanel content = new ScrollablePanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setOpaque(false);
        content.add(labeled("Skill", skillSelect));
        content.add(gap(8));
        content.add(pair("Current level", currentLevel, "Current XP", currentXp));
        content.add(gap(8));
        content.add(pair("Target level", targetLevel, "Target XP", targetXp));
        content.add(gap(8));
        content.add(loadXp);
        sectionBreak(content);
        content.add(labeled("Search methods / variants", search));
        content.add(gap(8));
        content.add(labeled("Sort", sortSelect));
        content.add(gap(6));
        content.add(hideLocked);
        content.add(gap(4));
        ranking.setForeground(SUBTEXT);
        content.add(ranking);
        content.add(gap(8));
        list.setSelectionMode(javax.swing.ListSelectionModel.SINGLE_SELECTION);
        rowRenderer.add(rowName, BorderLayout.NORTH);
        rowRenderer.add(rowDescription, BorderLayout.CENTER);
        rowRenderer.setBorder(BorderFactory.createEmptyBorder(8, 6, 8, 6));
        rowName.setFont(rowName.getFont().deriveFont(rowName.getFont().getSize2D() + 1));
        rowDescription.setFont(rowDescription.getFont().deriveFont(rowDescription.getFont().getSize2D() - 1));
        list.setCellRenderer((view, row, index, selected, focus) -> renderRow(row, selected));
        JScrollPane methodScroll = new JScrollPane(list);
        methodScroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        methodScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        methodScroll.setPreferredSize(new Dimension(200, 280));
        methodScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 280));
        JPanel methodSection = labeled("Method", methodScroll);
        methodSection.setMaximumSize(new Dimension(Integer.MAX_VALUE, methodSection.getPreferredSize().height));
        content.add(methodSection);
        content.add(empty);
        content.add(gap(8));
        variantRow = labeled("Variant", variants);
        variantRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
        content.add(variantRow);
        batchRow = labeled("Essence per batch", batchSize);
        batchRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
        content.add(batchRow);
        sectionBreak(content);
        content.add(optional);
        content.add(gap(6));
        content.add(sell);
        content.add(gap(6));
        content.add(tax);
        sectionBreak(content);
        content.add(refresh);
        content.add(gap(10));
        content.add(renderer.getComponent());
        for (Component component : content.getComponents())
        {
            if (component instanceof javax.swing.JComponent)
            {
                ((javax.swing.JComponent) component).setAlignmentX(Component.LEFT_ALIGNMENT);
            }
        }
        JScrollPane scroll = new JScrollPane(content);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        add(scroll, BorderLayout.CENTER);

        skillSelect.addActionListener(event -> switchSkill());
        sortSelect.addActionListener(event -> changed(true));
        hideLocked.addActionListener(event -> changed(true));
        listen(search, () -> {
            if (syncing || disposed) { return; }
            goal().search = search.getText();
            changed(true);
        });
        for (JSpinner field : new JSpinner[]{currentLevel, currentXp, targetLevel, targetXp})
        {
            boolean current = field == currentLevel || field == currentXp;
            boolean level = field == currentLevel || field == targetLevel;
            field.addChangeListener(event -> edit(field, current, level));
            listen(editor(field), () -> edit(field, current, level));
        }
        list.addListSelectionListener(event -> {
            if (!event.getValueIsAdjusting() && !syncing && !disposed)
            {
                rememberSelection();
                updateControls();
                changed(false);
            }
        });
        variants.addActionListener(event -> {
            if (syncing || disposed || list.getSelectedValue() == null) { return; }
            list.getSelectedValue().setSelectedVariantIndex(variants.getSelectedIndex());
            rememberSelection();
            updateControls();
            changed(false);
        });
        optional.addActionListener(event -> { session.optional = optional.isSelected(); changed(false); });
        sell.addActionListener(event -> { session.sell = sell.isSelected(); changed(false); });
        tax.addActionListener(event -> { session.tax = tax.isSelected(); changed(false); });
        batchSize.addChangeListener(event -> editBatch());
        listen(editor(batchSize), this::editBatch);
        loadXp.addActionListener(event -> loadCurrentXp());
        refresh.addActionListener(event -> { ++revision; scheduler.stop(); estimate(true); });
        switchSkill();
    }

    private CalculatorSession.Goal goal() { return session.goal(skill); }

    private void switchSkill()
    {
        if (disposed || syncing) { return; }
        skill = (Skill) skillSelect.getSelectedItem();
        ++xpLoadRevision;
        syncFields();
        changed(true);
        if (!goal().xpLoaded) { loadCurrentXp(); }
    }

    private void syncFields()
    {
        syncing = true;
        currentXp.setValue(goal().currentXp);
        currentLevel.setValue(CalculatorSession.level(goal().currentXp));
        targetXp.setValue(goal().targetXp);
        targetLevel.setValue(CalculatorSession.level(goal().targetXp));
        search.setText(goal().search);
        syncing = false;
        validInputs = true;
    }

    private void edit(JSpinner field, boolean current, boolean level)
    {
        if (syncing || disposed || skill == null) { return; }
        ++revision;
        estimates = Collections.emptyMap();
        scheduler.stop();
        goal().xpEditRevision++;
        try
        {
            int value = parsed(field);
            int xp = level ? Experience.getXpForLevel(value) : value;
            if (current) { goal().current(xp, false); }
            else { goal().target(xp); }
            syncing = true;
            (current ? (level ? currentXp : currentLevel) : (level ? targetXp : targetLevel))
                .setValue(level ? xp : CalculatorSession.level(xp));
            if (current && !goal().explicitTarget)
            {
                targetXp.setValue(goal().targetXp);
                targetLevel.setValue(CalculatorSession.level(goal().targetXp));
            }
            syncing = false;
            validateInputs();
            validInputs = true;
            rebuildRows();
            renderer.showStatus("Updating estimate…");
            scheduler.restart();
        }
        catch (ParseException | IllegalArgumentException exception)
        {
            syncing = false;
            validInputs = false;
            renderer.showStatus("Enter valid levels (1–99) and XP (0–200,000,000). Displayed result uses previous inputs.");
        }
    }

    private static int parsed(JSpinner spinner) throws ParseException
    {
        JFormattedTextField field = editor(spinner);
        Object parsed = field.getFormatter().stringToValue(field.getText());
        if (!(parsed instanceof Number)) { throw new ParseException("Invalid number", 0); }
        double value = ((Number) parsed).doubleValue();
        SpinnerNumberModel model = (SpinnerNumberModel) spinner.getModel();
        int minimum = ((Number) model.getMinimum()).intValue();
        int maximum = ((Number) model.getMaximum()).intValue();
        if (!Double.isFinite(value) || value != Math.rint(value) || value < minimum || value > maximum)
        {
            throw new ParseException("Out of range", 0);
        }
        return (int) value;
    }

    private void validateInputs() throws ParseException
    {
        for (JSpinner candidate : new JSpinner[]{currentLevel, currentXp, targetLevel, targetXp, batchSize}) { parsed(candidate); }
    }

    private void editBatch()
    {
        if (syncing || disposed) { return; }
        ++revision;
        estimates = Collections.emptyMap();
        scheduler.stop();
        try
        {
            session.batchSize = parsed(batchSize);
            validateInputs();
            validInputs = true;
            changed(false);
        }
        catch (ParseException | IllegalArgumentException exception)
        {
            validInputs = false;
            renderer.showStatus("Enter a batch size from 1 to 1,000. Displayed result uses previous inputs.");
        }
        updateControls();
    }

    private void loadCurrentXp()
    {
        Skill requestedSkill = skill;
        CalculatorSession.Goal requestedGoal = goal();
        long edit = requestedGoal.xpEditRevision;
        long loadRevision = ++xpLoadRevision;
        controller.loadCurrentSkillXp(requestedSkill, xp -> {
            if (disposed || loadRevision != xpLoadRevision || skill != requestedSkill || goal() != requestedGoal) { return; }
            if (xp < 0)
            {
                renderer.showStatus("Log in to load XP, or enter it manually.");
                return;
            }
            if (!requestedGoal.applyLoaded(xp, edit)) { return; }
            syncFields();
            changed(true);
        });
    }

    private void changed(boolean rebuild)
    {
        if (syncing || disposed) { return; }
        ++revision;
        estimates = Collections.emptyMap();
        if (rebuild) { rebuildRows(); }
        else { list.repaint(); }
        scheduler.stop();
        if (validInputs)
        {
            renderer.showStatus(rows.isEmpty() ? "No matching methods." : "Updating estimate…");
            scheduler.restart();
        }
    }

    private void rebuildRows()
    {
        String selectedId = goal().selectedId;
        List<MethodListEntry> visible = new ArrayList<>();
        for (MethodListEntry row : MethodListEntry.build(methods.get(skill)))
        {
            MethodListEntry filtered = row.filtered(goal().search, CalculatorSession.level(goal().currentXp),
                hideLocked.isSelected(), goal().variants.get(row.getDisplayName()));
            if (filtered != null) { visible.add(filtered); }
        }
        sortRows(visible);
        syncing = true;
        rows.clear();
        int selection = 0;
        for (int i = 0; i < visible.size(); i++)
        {
            MethodListEntry row = visible.get(i);
            rows.addElement(row);
            if (row.getSelected().getId().equals(selectedId)) { selection = i; }
        }
        if (!rows.isEmpty()) { list.setSelectedIndex(selection); }
        syncing = false;
        empty.setVisible(rows.isEmpty());
        rememberSelection();
        updateControls();
    }

    private void sortRows(List<MethodListEntry> visible)
    {
        Comparator<MethodListEntry> comparator;
        if (sortSelect.getSelectedItem() == MethodSort.MOST_PROFITABLE)
        {
            comparator = Comparator.comparing((MethodListEntry row) -> !available(row))
                .thenComparing((a, b) -> available(a) && available(b)
                    ? Long.compare(estimates.get(b.getSelected().getId()).getNet(), estimates.get(a.getSelected().getId()).getNet()) : 0);
        }
        else
        {
            comparator = Comparator.comparingLong(row -> row.getSelected().actionsFor(Math.max(0, goal().targetXp - goal().currentXp)));
        }
        visible.sort(comparator.thenComparing(MethodListEntry::getDisplayName));
    }

    private boolean available(MethodListEntry row)
    {
        CostResult result = estimates.get(row.getSelected().getId());
        return result != null && result.isAvailable();
    }

    private void rememberSelection()
    {
        MethodListEntry row = list.getSelectedValue();
        goal().selectedId = row == null ? null : row.getSelected().getId();
        if (row != null) { goal().variants.put(row.getDisplayName(), goal().selectedId); }
    }

    private void updateControls()
    {
        MethodListEntry row = list.getSelectedValue();
        SkillingMethod selected = row == null ? null : row.getSelected();
        syncing = true;
        variants.setModel(new DefaultComboBoxModel<>(row == null ? new SkillingMethod[0] : row.getVariants().toArray(new SkillingMethod[0])));
        if (row != null) { variants.setSelectedIndex(row.getSelectedVariantIndex()); }
        syncing = false;
        variantRow.setVisible(row != null && row.hasVariants());
        batchRow.setVisible(selected != null && selected.usesBatches());
        refresh.setEnabled(selected != null && validInputs);
    }

    void estimate(boolean forceRefresh)
    {
        if (disposed || !validInputs || list.getSelectedValue() == null) { return; }
        List<SkillingMethod> requested = new ArrayList<>();
        if (sortSelect.getSelectedItem() == MethodSort.MOST_PROFITABLE)
        {
            for (int i = 0; i < rows.size(); i++) { requested.addAll(rows.get(i).getVariants()); }
        }
        else { requested.add(list.getSelectedValue().getSelected()); }
        CalculationRequest request = new CalculationRequest(revision, requested, goal().selectedId,
            goal().currentXp, goal().targetXp, CalculatorSession.level(goal().currentXp),
            CalculatorSession.level(goal().targetXp), session.batchSize, session.optional, session.sell, session.tax, forceRefresh);
        renderer.showStatus(forceRefresh ? "Refreshing prices…" : "Estimating…");
        controller.estimate(request, results -> {
            if (disposed || revision != request.revision) { return; }
            estimates = results;
            rebuildRows();
            CostResult result = results.get(request.selectedId);
            if (result != null) { renderer.showResult(result); }
        }, message -> {
            if (disposed || revision != request.revision) { return; }
            estimates = Collections.emptyMap();
            list.repaint();
            renderer.showFailure(message);
        });
    }

    void pricesChanged() { changed(true); }
    void dispose() { disposed = true; ++revision; scheduler.stop(); estimates = Collections.emptyMap(); }

    private Component renderRow(MethodListEntry row, boolean selected)
    {
        SkillingMethod method = row.getSelected();
        rowRenderer.setBackground(selected ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
        int width = Math.max(80, list.getWidth() > 0
            ? list.getWidth() - rowRenderer.getInsets().left - rowRenderer.getInsets().right : 180);
        rowName.setText(row.getDisplayName());
        rowName.setForeground(TEXT);
        String detail = "Lvl " + method.getRequiredLevel() + " · " + method.getXpPerAction() + " XP";
        CostResult result = estimates.get(method.getId());
        if (sortSelect.getSelectedItem() == MethodSort.MOST_PROFITABLE)
        {
            detail += " · " + (result == null ? "Net pending" : result.isAvailable() ? Formats.gpCompact(result.getNet()) : "Unavailable");
        }
        else { detail += " · " + String.format("%,d", method.actionsFor(Math.max(0, goal().targetXp - goal().currentXp))) + " actions"; }
        rowDescription.setText(detail);
        rowDescription.setForeground(CalculatorSession.level(goal().currentXp) < method.getRequiredLevel() ? LOSS : SUBTEXT);
        sizeRowText(rowName, width);
        sizeRowText(rowDescription, width);
        rowRenderer.setSize(width + rowRenderer.getInsets().left + rowRenderer.getInsets().right,
            rowRenderer.getPreferredSize().height);
        rowRenderer.doLayout();
        return rowRenderer;
    }

    private static javax.swing.JTextArea rowText()
    {
        javax.swing.JTextArea area = new javax.swing.JTextArea();
        area.setEditable(false);
        area.setFocusable(false);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setOpaque(false);
        area.setFont(new JLabel().getFont());
        return area;
    }

    private static void sizeRowText(javax.swing.JTextArea area, int width)
    {
        area.setPreferredSize(null);
        area.setSize(new Dimension(width, Short.MAX_VALUE));
        Dimension size = area.getPreferredSize();
        size.width = width;
        area.setPreferredSize(size);
    }

    private static JSpinner spinner(int value, int min, int max)
    {
        JSpinner spinner = new JSpinner(new SpinnerNumberModel(value, min, max, 1));
        spinner.setEditor(new JSpinner.NumberEditor(spinner, "#,##0"));
        return spinner;
    }
    private static JFormattedTextField editor(JSpinner spinner) { return ((JSpinner.DefaultEditor) spinner.getEditor()).getTextField(); }
    private static void listen(JTextField field, Runnable action)
    {
        field.getDocument().addDocumentListener(new DocumentListener()
        {
            public void insertUpdate(DocumentEvent event) { action.run(); }
            public void removeUpdate(DocumentEvent event) { action.run(); }
            public void changedUpdate(DocumentEvent event) { action.run(); }
        });
    }
    private static JPanel labeled(String label, Component component)
    {
        JPanel panel = new JPanel(new BorderLayout(0, 3));
        panel.setOpaque(false);
        panel.add(new JLabel(label), BorderLayout.NORTH);
        panel.add(component, BorderLayout.CENTER);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 65));
        return panel;
    }
    private static JPanel pair(String left, Component a, String right, Component b)
    {
        JPanel panel = new JPanel(new GridLayout(1, 2, 6, 0));
        panel.setOpaque(false);
        panel.add(labeled(left, a));
        panel.add(labeled(right, b));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 65));
        return panel;
    }

    private static Component gap(int height)
    {
        return Box.createRigidArea(new Dimension(0, height));
    }

    private static void sectionBreak(JPanel content)
    {
        content.add(gap(10));
        JPanel divider = new JPanel();
        divider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        divider.setPreferredSize(new Dimension(1, 1));
        divider.setMinimumSize(new Dimension(1, 1));
        divider.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
        content.add(divider);
        content.add(gap(10));
    }
}

package com.skillingcost;

import com.google.inject.Provides;
import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
    name = "Skilling Cost Calculator",
    description = "Calculates skilling method cost with current XP and GE prices",
    tags = {"skilling", "calculator", "crafting", "herblore", "prayer", "ge", "prices"}
)
public class SkillingCostPlugin extends Plugin implements CalculatorController
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar clientToolbar;
    @Inject private SkillingCostConfig config;
    @Inject private PriceService priceService;
    @Inject private MethodRepository methodRepository;

    private volatile SkillingCostPanel panel;
    private NavigationButton navButton;
    private long panelGeneration;
    private volatile ExecutorService worker;
    private volatile long lifecycle;

    @Override
    protected void startUp()
    {
        long generation = ++lifecycle;
        ExecutorService executor = Executors.newSingleThreadExecutor(task -> {
            Thread thread = new Thread(task, "skilling-cost-calculator");
            thread.setDaemon(true);
            return thread;
        });
        worker = executor;
        executor.execute(() -> {
            try
            {
                // Bundled-resource IO and parsing run off the client thread.
                methodRepository.getMethodsBySkill();
                SwingUtilities.invokeLater(() -> {
                    if (generation != lifecycle) { return; }
                    removePanel();
                    panel = new SkillingCostPanel(this, methodRepository);
                    panelGeneration = generation;
                    navButton = NavigationButton.builder().tooltip("Skilling Cost Calculator")
                        .icon(ImageUtil.loadImageResource(SkillingCostPlugin.class, "/icon.png"))
                        .priority(8).panel(panel).build();
                    clientToolbar.addNavigation(navButton);
                });
            }
            catch (RuntimeException exception)
            {
                log.debug("Cannot load bundled skilling methods", exception);
            }
        });
    }

    @Override
    protected void shutDown()
    {
        long stoppedGeneration = ++lifecycle;
        priceService.cancel();
        ExecutorService executor = worker;
        worker = null;
        if (executor != null) { executor.shutdownNow(); }
        SwingUtilities.invokeLater(() -> {
            if (panelGeneration < stoppedGeneration) { removePanel(); }
        });
    }

    /** All panel/navigation ownership changes are serialized on the Swing EDT. */
    private void removePanel()
    {
        if (panel != null) { panel.dispose(); panel = null; }
        if (navButton != null) { clientToolbar.removeNavigation(navButton); navButton = null; }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"skilling-cost-calculator".equals(event.getGroup())) { return; }
        if ("enableWikiPrices".equals(event.getKey())) { priceService.cancel(); }
        long generation = lifecycle;
        SwingUtilities.invokeLater(() -> {
            SkillingCostPanel current = panel;
            if (generation == lifecycle && current != null) { current.pricesChanged(); }
        });
    }

    @Override
    public void loadCurrentSkillXp(Skill skill, IntConsumer callback)
    {
        long generation = lifecycle;
        clientThread.invokeLater(() -> {
            if (generation != lifecycle) { return; }
            int xp = client.getGameState() == GameState.LOGGED_IN
                ? Math.max(0, client.getSkillExperience(skill)) : -1;
            SwingUtilities.invokeLater(() -> {
                if (generation == lifecycle) { callback.accept(xp); }
            });
        });
    }

    @Override
    public void estimate(CalculationRequest request, Consumer<Map<String, CostResult>> success, Consumer<String> failure)
    {
        long generation = lifecycle;
        ExecutorService executor = worker;
        if (executor == null || executor.isShutdown()) { return; }
        CostCalculator.TaxSettings tax = new CostCalculator.TaxSettings(
            config.taxBasisPoints(), config.taxCapGp(), config.taxExemptBelowGp());
        priceService.getLatestSnapshot(request.priceIds(), request.refresh, snapshot -> {
            if (generation != lifecycle || executor.isShutdown()) { return; }
            try
            {
                executor.execute(() -> {
                    if (generation != lifecycle) { return; }
                    Map<String, CostResult> results = new LinkedHashMap<>();
                    Instant now = Instant.now();
                    for (SkillingMethod method : request.methods)
                    {
                        results.put(method.getId(), CostCalculator.calculate(method,
                            request.currentLevel, request.currentXp, request.targetLevel, request.targetXp,
                            request.optional, request.sell, request.tax, request.batchSize, snapshot, tax, now));
                    }
                    Map<String, CostResult> immutable = Collections.unmodifiableMap(results);
                    SwingUtilities.invokeLater(() -> {
                        if (generation == lifecycle) { success.accept(immutable); }
                    });
                });
            }
            catch (java.util.concurrent.RejectedExecutionException ignored)
            {
                // Shutdown raced with a response; its panel has already been invalidated.
            }
        }, message -> SwingUtilities.invokeLater(() -> {
            if (generation == lifecycle) { failure.accept(message); }
        }));
    }

    @Provides
    SkillingCostConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(SkillingCostConfig.class);
    }
}

package com.skillingcost;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Skill;

final class SkillingMethod
{
    private final Skill skill;
    private final String id;
    private final String name;
    private final String groupName;
    private final String variantName;
    private final int requiredLevel;
    private final double xpPerAction;
    private final List<ItemQuantity> requiredInputs;
    private final List<ItemQuantity> optionalInputs;
    private final List<ItemQuantity> outputs;
    private final String actionUnit;
    private final String source;
    private final String assumptions;
    private final int[] outputLevels;

    SkillingMethod(Skill skill, String name, String group, String variant, int level, double xp,
        List<ItemQuantity> inputs, List<ItemQuantity> optional, List<ItemQuantity> outputs)
    {
        this(skill, skill + ":" + name, name, group, variant, level, xp, inputs, optional, outputs,
            "action", "", "", new int[0]);
    }

    SkillingMethod(Skill skill, String id, String name, String group, String variant, int level, double xp,
        List<ItemQuantity> inputs, List<ItemQuantity> optional, List<ItemQuantity> outputs,
        String actionUnit, String source, String assumptions, int[] outputLevels)
    {
        if (skill == null || id == null || id.trim().isEmpty() || name == null || name.trim().isEmpty()
            || level < 1 || level > 99 || !Double.isFinite(xp) || xp <= 0
            || actionUnit == null || actionUnit.trim().isEmpty())
        {
            throw new IllegalArgumentException("Invalid recipe: " + name);
        }
        this.skill = skill;
        this.id = id;
        this.name = name;
        this.groupName = group;
        this.variantName = variant;
        this.requiredLevel = level;
        this.xpPerAction = xp;
        this.requiredInputs = Collections.unmodifiableList(new ArrayList<>(inputs));
        this.optionalInputs = Collections.unmodifiableList(new ArrayList<>(optional));
        this.outputs = Collections.unmodifiableList(new ArrayList<>(outputs));
        this.actionUnit = actionUnit;
        this.source = source == null ? "" : source;
        this.assumptions = assumptions == null ? "" : assumptions;
        this.outputLevels = outputLevels == null ? new int[0] : outputLevels.clone();
        int previous = level;
        for (int threshold : this.outputLevels)
        {
            if (threshold <= previous || threshold > 99)
            {
                throw new IllegalArgumentException("Invalid output threshold: " + name);
            }
            previous = threshold;
        }
    }

    Skill getSkill() { return skill; }
    String getId() { return id; }
    String getName() { return name; }
    String getGroupName() { return groupName; }
    String getVariantName() { return variantName; }
    int getRequiredLevel() { return requiredLevel; }
    double getXpPerAction() { return xpPerAction; }
    List<ItemQuantity> getRequiredInputs() { return requiredInputs; }
    List<ItemQuantity> getOptionalInputs() { return optionalInputs; }
    List<ItemQuantity> getOutputs() { return outputs; }
    String getActionUnit() { return actionUnit; }
    String getSource() { return source; }
    String getAssumptions() { return assumptions; }
    boolean hasSellableOutputs() { return outputs.stream().anyMatch(ItemQuantity::isGePriced); }
    boolean hasLevelDependentOutput() { return outputLevels.length > 0; }
    boolean usesBatches()
    {
        return requiredInputs.stream().anyMatch(ItemQuantity::isPerBatch)
            || optionalInputs.stream().anyMatch(ItemQuantity::isPerBatch);
    }

    int outputMultiplier(int level)
    {
        int multiplier = 1;
        for (int threshold : outputLevels)
        {
            if (level >= threshold)
            {
                multiplier++;
            }
        }
        return multiplier;
    }

    long actionsFor(int xpNeeded)
    {
        return xpNeeded <= 0 ? 0 : BigDecimal.valueOf(xpNeeded)
            .divide(BigDecimal.valueOf(xpPerAction), 0, RoundingMode.CEILING).longValueExact();
    }

    Set<Integer> getPriceItemIds(boolean optional, boolean sell)
    {
        Set<Integer> ids = new LinkedHashSet<>();
        addGeIds(ids, requiredInputs);
        if (optional) { addGeIds(ids, optionalInputs); }
        if (sell) { addGeIds(ids, outputs); }
        return ids;
    }

    private static void addGeIds(Set<Integer> ids, List<ItemQuantity> items)
    {
        for (ItemQuantity item : items)
        {
            if (item.isGePriced() && item.getQuantityPerAction().signum() > 0)
            {
                ids.add(item.getItemId());
            }
        }
    }

    @Override
    public String toString() { return name; }
}

package com.skillingcost;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

/** Parse independently so one invalid or expensive item cannot break the feed. */
final class WikiLatestResponse
{
    private WikiLatestResponse()
    {
    }

    static Map<Integer, WikiPrice> parse(Gson gson, String json)
    {
        JsonObject root = gson.fromJson(json, JsonObject.class);
        if (root == null || !root.has("data") || !root.get("data").isJsonObject())
        {
            throw new IllegalArgumentException("Invalid price response");
        }
        Map<Integer, WikiPrice> prices = new HashMap<>();
        for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject("data").entrySet())
        {
            try
            {
                int id = Integer.parseInt(entry.getKey());
                if (id <= 0 || !entry.getValue().isJsonObject())
                {
                    continue;
                }
                JsonObject item = entry.getValue().getAsJsonObject();
                prices.put(id, new WikiPrice(number(item.get("high")), number(item.get("low")),
                    number(item.get("highTime")), number(item.get("lowTime"))));
            }
            catch (NumberFormatException ignored)
            {
                // Non-item keys do not invalidate other quotes.
            }
        }
        return prices;
    }

    private static Long number(JsonElement value)
    {
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
        {
            return null;
        }
        try
        {
            long parsed = new BigDecimal(value.getAsString()).longValueExact();
            return parsed > 0 ? parsed : null;
        }
        catch (ArithmeticException | NumberFormatException ignored)
        {
            return null;
        }
    }
}

package com.skillingcost;

/** Immutable trade quotes; absence is distinct from a zero GP valuation. */
final class WikiPrice
{
    private final Long high;
    private final Long low;
    private final Long highTime;
    private final Long lowTime;

    WikiPrice(Long high, Long low, Long highTime, Long lowTime)
    {
        this.high = positive(high);
        this.low = positive(low);
        this.highTime = positive(highTime);
        this.lowTime = positive(lowTime);
    }

    Quote buyQuote()
    {
        return high != null ? new Quote(high, highTime, false, "instant buy")
            : low != null ? new Quote(low, lowTime, true, "instant sell") : null;
    }

    Quote sellQuote()
    {
        return low != null ? new Quote(low, lowTime, false, "instant sell")
            : high != null ? new Quote(high, highTime, true, "instant buy") : null;
    }

    private static Long positive(Long value)
    {
        return value != null && value > 0 ? value : null;
    }

    static final class Quote
    {
        final long gp;
        final Long timestamp;
        final boolean fallback;
        final String side;

        Quote(long gp, Long timestamp, boolean fallback, String side)
        {
            this.gp = gp;
            this.timestamp = timestamp;
            this.fallback = fallback;
            this.side = side;
        }
    }
}

package com.skillingcost;

import com.google.gson.Gson;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.swing.JSpinner;
import javax.swing.SwingUtilities;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class CalculatorFlowTest
{
    private static final Instant NOW = Instant.ofEpochSecond(1000);
    private static final CostCalculator.TaxSettings TAX = new CostCalculator.TaxSettings(200, 5_000_000, 50);

    private static final class Schedule implements EstimateScheduler
    {
        Runnable action;
        boolean pending;
        int stops;
        public void restart() { pending = true; }
        public void stop() { pending = false; stops++; }
        void fire() { if (pending) { pending = false; action.run(); } }
    }

    private static final class Controller implements CalculatorController
    {
        final List<IntConsumer> xp = new ArrayList<>();
        final List<CalculationRequest> requests = new ArrayList<>();
        final List<Consumer<Map<String, CostResult>>> successes = new ArrayList<>();
        final List<Consumer<String>> failures = new ArrayList<>();
        public void loadCurrentSkillXp(Skill skill, IntConsumer callback) { xp.add(callback); }
        public void estimate(CalculationRequest request, Consumer<Map<String, CostResult>> success, Consumer<String> failure)
        {
            requests.add(request); successes.add(success); failures.add(failure);
        }
        void succeed(int index)
        {
            CalculationRequest request = requests.get(index);
            Map<Integer, WikiPrice> prices = new HashMap<>();
            for (int id : request.priceIds()) { prices.put(id, new WikiPrice(100L, 99L, 900L, 800L)); }
            PriceSnapshot snapshot = new PriceSnapshot(prices, NOW);
            Map<String, CostResult> results = new HashMap<>();
            for (SkillingMethod method : request.methods)
            {
                results.put(method.getId(), CostCalculator.calculate(method, request.currentLevel, request.currentXp,
                    request.targetLevel, request.targetXp, request.optional, request.sell, request.tax,
                    request.batchSize, snapshot, TAX, NOW));
            }
            successes.get(index).accept(results);
        }
    }

    private SkillingCostPanel panel(Controller controller, Schedule schedule)
    {
        return new SkillingCostPanel(controller, new MethodRepository(new Gson()), action -> {
            schedule.action = action;
            return schedule;
        });
    }

    @Test
    public void goalsPreserveExplicitTargetsAndLevel99()
    {
        CalculatorSession state = new CalculatorSession();
        CalculatorSession.Goal goal = state.goal(Skill.COOKING);
        assertEquals(Experience.getXpForLevel(2), goal.targetXp);
        goal.current(Experience.getXpForLevel(50), true);
        assertEquals(Experience.getXpForLevel(51), goal.targetXp);
        goal.target(1_000_000);
        goal.current(Experience.getXpForLevel(60), true);
        assertEquals(1_000_000, goal.targetXp);
        assertSame(goal, state.goal(Skill.COOKING));
        CalculatorSession.Goal maximum = state.goal(Skill.MAGIC);
        maximum.current(200_000_000, true);
        assertEquals(200_000_000, maximum.targetXp);
        assertFalse(maximum.applyLoaded(0, maximum.xpEditRevision - 1));
        assertFalse(maximum.applyLoaded(-1, maximum.xpEditRevision));
    }

    @Test
    public void coalescingManualTextAndLateXp()
        throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Controller controller = new Controller(); Schedule schedule = new Schedule();
            SkillingCostPanel panel = panel(controller, schedule);
            panel.currentXp.setValue(100);
            panel.currentXp.setValue(200);
            panel.targetXp.setValue(1000);
            assertEquals(0, controller.requests.size());
            schedule.fire();
            assertEquals(1, controller.requests.size());
            assertEquals(200, controller.requests.get(0).currentXp);
            ((JSpinner.DefaultEditor) panel.currentXp.getEditor()).getTextField().setText("invalid");
            controller.xp.get(0).accept(5000);
            assertEquals(200, panel.session.goal(Skill.SMITHING).currentXp);
            assertFalse(schedule.pending);
            ((JSpinner.DefaultEditor) panel.currentXp.getEditor()).getTextField().setText("300");
            schedule.fire();
            assertEquals(300, controller.requests.get(1).currentXp);
            assertEquals(1000, controller.requests.get(1).targetXp);
            panel.dispose();
            assertFalse(schedule.pending);
        });
    }

    @Test
    public void globalOptionsStayEditableAcrossSkillsAndEmptySelections()
        throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Controller controller = new Controller(); Schedule schedule = new Schedule();
            SkillingCostPanel panel = panel(controller, schedule);
            panel.targetXp.setValue(10000);
            panel.sell.doClick();
            panel.search.setText("iron");
            panel.skillSelect.setSelectedItem(Skill.FIREMAKING);
            assertTrue(panel.optional.isEnabled());
            assertTrue(panel.sell.isEnabled());
            assertTrue(panel.tax.isEnabled());
            assertFalse(panel.session.sell);
            // Preferences can be changed even when this recipe has no outputs or optional inputs.
            panel.tax.doClick();
            panel.optional.doClick();
            panel.search.setText("NO MATCH EXISTS");
            assertEquals(0, panel.rows.size());
            assertTrue(panel.optional.isEnabled());
            assertTrue(panel.sell.isEnabled());
            assertTrue(panel.tax.isEnabled());
            panel.sell.doClick();
            panel.skillSelect.setSelectedItem(Skill.SMITHING);
            assertEquals(10000, panel.session.goal(Skill.SMITHING).targetXp);
            assertEquals("iron", panel.search.getText());
            assertFalse(panel.optional.isSelected());
            assertTrue(panel.sell.isSelected());
            assertFalse(panel.tax.isSelected());
            schedule.fire();
            CalculationRequest request = controller.requests.get(0);
            assertFalse(request.optional);
            assertTrue(request.sell);
            assertFalse(request.tax);
            controller.xp.get(0).accept(90000);
            assertEquals(0, panel.session.goal(Skill.SMITHING).currentXp);
            panel.dispose();
        });
    }

    @Test
    public void selectedMethodVariantAndTargetSurviveSkillChangesSortAndXpReload() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Controller controller = new Controller(); Schedule schedule = new Schedule();
            SkillingCostPanel panel = panel(controller, schedule);
            panel.skillSelect.setSelectedItem(Skill.PRAYER);
            panel.currentLevel.setValue(99);
            panel.targetXp.setValue(20_000_000);
            panel.search.setText("dragon");
            for (int index = 0; index < panel.rows.size(); index++)
            {
                if (panel.rows.get(index).hasVariants()) { panel.list.setSelectedIndex(index); break; }
            }
            assertTrue(panel.variants.getItemCount() > 1);
            panel.variants.setSelectedIndex(panel.variants.getItemCount() - 1);
            String selectedId = panel.list.getSelectedValue().getSelected().getId();
            panel.skillSelect.setSelectedItem(Skill.COOKING);
            panel.skillSelect.setSelectedItem(Skill.PRAYER);
            assertEquals("dragon", panel.search.getText());
            assertEquals(20_000_000, panel.targetXp.getValue());
            assertEquals(selectedId, panel.list.getSelectedValue().getSelected().getId());
            assertEquals(selectedId, ((SkillingMethod) panel.variants.getSelectedItem()).getId());
            panel.sortSelect.setSelectedItem(SkillingCostPanel.MethodSort.MOST_PROFITABLE);
            schedule.fire();
            controller.succeed(0);
            assertEquals(selectedId, panel.renderer.displayedResult().getMethod().getId());
            panel.loadXp.doClick();
            controller.xp.get(controller.xp.size() - 1).accept(14_000_000);
            assertEquals(20_000_000, panel.targetXp.getValue());
            assertEquals(selectedId, panel.list.getSelectedValue().getSelected().getId());
            panel.dispose();
        });
    }

    @Test
    public void obsoleteResponsesCannotChangePanelAfterAnyInputOrDisposal()
        throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Controller controller = new Controller(); Schedule schedule = new Schedule();
            SkillingCostPanel panel = panel(controller, schedule);
            schedule.fire();
            panel.sortSelect.setSelectedItem(SkillingCostPanel.MethodSort.MOST_PROFITABLE);
            controller.succeed(0);
            assertNull(panel.renderer.displayedResult());
            schedule.fire();
            controller.succeed(1);
            CostResult baseline = panel.renderer.displayedResult();
            assertNotNull(baseline);
            panel.targetXp.setValue(2000); schedule.fire();
            panel.tax.doClick(); schedule.fire();
            panel.search.setText("steel"); schedule.fire();
            panel.hideLocked.doClick(); schedule.fire();
            controller.succeed(2);
            controller.succeed(3);
            controller.failures.get(4).accept("OLD FAILURE");
            assertSame(baseline, panel.renderer.displayedResult());
            assertFalse(panel.renderer.statusText().contains("OLD FAILURE"));
            panel.dispose();
            controller.succeed(controller.requests.size() - 1);
            assertSame(baseline, panel.renderer.displayedResult());
            SkillingCostPanel replacement = panel(controller, new Schedule());
            assertNull(replacement.renderer.displayedResult());
            replacement.dispose();
        });
    }

    @Test
    public void filteringAndSelectedVariantRankingUseIdenticalResults()
        throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Controller controller = new Controller(); Schedule schedule = new Schedule();
            SkillingCostPanel panel = panel(controller, schedule);
            panel.skillSelect.setSelectedItem(Skill.PRAYER);
            panel.currentLevel.setValue(40);
