public class PriceServiceTest
{
    private final FakeClock clock = new FakeClock();
    private final FakeCalls calls = new FakeCalls();
    private final TestConfig config = new TestConfig();
    private final PriceService service = new PriceService(calls, new Gson(), config, clock);

    @Test
    public void requestsBulkV2LatestWithMaintainerContact()
    {
        service.getLatestSnapshot(Collections.singleton(1), false, x -> {}, this::fail);
        Request request = calls.list.get(0).request();
        assertEquals("GET", request.method());
        assertEquals("https://prices.runescape.wiki/api/v2/osrs/latest", request.url().toString());
        assertEquals("skilling-cost-calculator RuneLite plugin (contact: junk.ladybird471@proton.me)",
            request.header("User-Agent"));
    }

    @Test
    public void blankAndLegacySavedAgentsUseTheContactDefault()
    {
        for (String savedAgent : new String[] {null, "", "  ", "skilling-cost-calculator RuneLite plugin",
            "  skilling-cost-calculator RuneLite plugin  "})
        {
            FakeCalls savedCalls = new FakeCalls();
            SkillingCostConfig savedConfig = new SkillingCostConfig()
            {
                @Override public String wikiUserAgent() { return savedAgent; }
            };
            PriceService savedService = new PriceService(savedCalls, new Gson(), savedConfig, clock);
            savedService.getLatestSnapshot(Collections.singleton(1), false, x -> {}, this::fail);
            assertEquals("skilling-cost-calculator RuneLite plugin (contact: junk.ladybird471@proton.me)",
                savedCalls.list.get(0).request().header("User-Agent"));
        }
    }

    @Test
    public void preservesCustomUserAgent()
    {
        SkillingCostConfig customConfig = new SkillingCostConfig()
        {
            @Override public String wikiUserAgent() { return "  custom-calculator contact@example.com  "; }
        };
        PriceService customService = new PriceService(calls, new Gson(), customConfig, clock);
        customService.getLatestSnapshot(Collections.singleton(1), false, x -> {}, this::fail);
        assertEquals("custom-calculator contact@example.com", calls.list.get(0).request().header("User-Agent"));
    }

    @Test
    public void sharesRequestsCachesAbsenceAndInvokesOutsideLock() throws Exception
    {
        List<PriceSnapshot> received = new ArrayList<>();
        service.getLatestSnapshot(Collections.singleton(1), false, snapshot -> {
            received.add(snapshot);
            service.getLatestSnapshot(Collections.singleton(3), false, received::add, this::fail);
        }, this::fail);
        service.getLatestSnapshot(Collections.singleton(2), false, received::add, this::fail);
        assertEquals(1, calls.list.size());
        calls.list.get(0).respond(200, "{\"data\":{\"1\":{\"high\":2450000000}}}");
        assertEquals(3, received.size());
        assertEquals(1, calls.list.size());
        assertTrue(received.get(1).prices.isEmpty());
        assertEquals(clock.instant(), received.get(0).fetchedAt);
        clock.seconds += 59;
        service.getLatestSnapshot(Collections.singleton(2), false, received::add, this::fail);
        assertEquals(1, calls.list.size());
        clock.seconds++;
        service.getLatestSnapshot(Collections.singleton(2), false, received::add, this::fail);
        assertEquals(2, calls.list.size());
        calls.list.get(1).respond(200, "{\"data\":{}}");
        service.getLatestSnapshot(Collections.singleton(2), false, received::add, this::fail);
        assertEquals(2, calls.list.size());
    }

    @Test
    public void refreshJoinsInflightAndCancellationRejectsOldCompletion() throws Exception
    {
        AtomicInteger received = new AtomicInteger();
        service.getLatestSnapshot(Collections.singleton(1), false, x -> received.incrementAndGet(), this::fail);
        FakeCall old = calls.list.get(0);
        service.getLatestSnapshot(Collections.singleton(2), true, x -> received.incrementAndGet(), this::fail);
        assertEquals(1, calls.list.size());
        service.cancel();
        assertTrue(old.isCanceled());
        service.getLatestSnapshot(Collections.singleton(1), false, x -> received.incrementAndGet(), this::fail);
        old.respond(200, "{\"data\":{}}");
        assertEquals(0, received.get());
        service.getLatestSnapshot(Collections.singleton(2), true, x -> received.incrementAndGet(), this::fail);
        assertEquals(2, calls.list.size());
        calls.list.get(1).respond(200, "{\"data\":{}}");
        assertEquals(2, received.get());
        service.getLatestSnapshot(Collections.singleton(1), true, x -> received.incrementAndGet(), this::fail);
        assertEquals(3, calls.list.size());
    }

    @Test
    public void disabledPricesAndNoQuoteWorkSendNoRequests()
    {
        config.enabled = false;
        List<String> errors = new ArrayList<>();
        service.getLatestSnapshot(Collections.singleton(1), false, x -> fail("unexpected success"), errors::add);
        AtomicInteger received = new AtomicInteger();
        service.getLatestSnapshot(Collections.emptySet(), true, x -> received.incrementAndGet(), errors::add);
        assertEquals(1, errors.size());
        assertEquals(1, received.get());
        assertTrue(calls.list.isEmpty());
    }

    @Test
    public void errorsDoNotRefreshOldSnapshot() throws Exception
    {
        List<String> errors = new ArrayList<>();
        service.getLatestSnapshot(Collections.singleton(1), false, x -> {}, errors::add);
        calls.list.get(0).respond(200, "{\"data\":{}}");
        clock.seconds += 60;
        service.getLatestSnapshot(Collections.singleton(1), false, x -> fail("unexpected success"), errors::add);
        calls.list.get(1).respond(500, "error");
        service.getLatestSnapshot(Collections.singleton(1), false, x -> fail("unexpected success"), errors::add);
        assertEquals(3, calls.list.size());
        calls.list.get(2).respond(200, "{\"data\":null}");
        service.getLatestSnapshot(Collections.singleton(1), false, x -> fail("unexpected success"), errors::add);
        calls.list.get(3).callback.onFailure(calls.list.get(3), new IOException("raw internal detail"));
        assertEquals(3, errors.size());
        assertFalse(String.join(" ", errors).contains("raw internal detail"));
    }

    private void fail(String error) { org.junit.Assert.fail(error); }

    @Test
    public void disableReenableAndEnqueueFailureReleaseAcquisition() throws Exception
    {
        List<String> errors = new ArrayList<>();
        AtomicInteger received = new AtomicInteger();
        service.getLatestSnapshot(Collections.singleton(1), false, x -> received.incrementAndGet(), errors::add);
        FakeCall obsolete = calls.list.get(0);
        config.enabled = false;
        service.cancel();
        obsolete.respond(200, "{\"data\":{}}");
        assertEquals(0, received.get());
        service.getLatestSnapshot(Collections.singleton(1), false, x -> received.incrementAndGet(), errors::add);
        assertEquals(1, calls.list.size());
        config.enabled = true;
        calls.failEnqueue = true;
        service.getLatestSnapshot(Collections.singleton(1), false, x -> received.incrementAndGet(), errors::add);
        assertEquals(2, errors.size());
        calls.failEnqueue = false;
        service.getLatestSnapshot(Collections.singleton(1), false, x -> received.incrementAndGet(), errors::add);
        calls.list.get(2).respond(200, "{\"data\":{}}");
        assertEquals(1, received.get());
        assertEquals(3, calls.list.size());
    }

    private static final class TestConfig implements SkillingCostConfig
    {
        boolean enabled = true;
        @Override public boolean enableWikiPrices() { return enabled; }
    }

    private static final class FakeClock extends Clock
    {
        long seconds = 1000;
        @Override public ZoneId getZone() { return ZoneId.of("UTC"); }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return Instant.ofEpochSecond(seconds); }
    }

    private static final class FakeCalls implements Call.Factory
    {
        final List<FakeCall> list = new ArrayList<>();
        boolean failEnqueue;
        @Override public Call newCall(Request request)
        {
            FakeCall call = new FakeCall(request);
            call.failEnqueue = failEnqueue;
            list.add(call);
            return call;
        }
    }

    private static final class FakeCall implements Call
    {
        final Request request;
        Callback callback;
        boolean canceled;
        boolean failEnqueue;
        FakeCall(Request request) { this.request = request; }
        void respond(int code, String body) throws IOException
        {
            callback.onResponse(this, new Response.Builder().request(request).protocol(Protocol.HTTP_1_1)
                .code(code).message("fixture").body(ResponseBody.create(MediaType.parse("application/json"), body)).build());
        }
        @Override public Request request() { return request; }
        @Override public Response execute() { throw new UnsupportedOperationException(); }
        @Override public void enqueue(Callback callback)
        {
            if (failEnqueue) { throw new IllegalStateException("fixture queue failure"); }
            this.callback = callback;
        }
        @Override public void cancel() { canceled = true; }
        @Override public boolean isExecuted() { return callback != null; }
        @Override public boolean isCanceled() { return canceled; }
        @Override public Timeout timeout() { return Timeout.NONE; }
        @Override public Call clone() { return new FakeCall(request); }
    }
}

package com.skillingcost;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.imageio.ImageIO;
import javax.swing.JLabel;
import javax.swing.JToggleButton;
import javax.swing.SwingUtilities;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class ResultRendererTest
{
    private final Instant now = Instant.ofEpochSecond(1000);
    private final CostCalculator.TaxSettings tax = new CostCalculator.TaxSettings(200, 5_000_000, 50);

    private CostResult estimate(WikiPrice quote)
    {
        SkillingMethod method = new SkillingMethod(Skill.MAGIC, "Fixture production", null, null, 1, 1,
            Collections.emptyList(), Collections.emptyList(), Collections.singletonList(new ItemQuantity(1, "output", 1)));
        return CostCalculator.calculate(method, 1, 0, 1, 1, true, true, true, 28,
            new PriceSnapshot(quote == null ? Collections.emptyMap() : Collections.singletonMap(1, quote), now), tax, now);
    }

    private List<Component> descendants(Container parent)
    {
        List<Component> components = new ArrayList<>();
        for (Component component : parent.getComponents())
        {
            components.add(component);
            if (component instanceof Container) { components.addAll(descendants((Container) component)); }
        }
        return components;
    }

    private void layout(Container container)
    {
        container.doLayout();
        for (Component child : container.getComponents()) { if (child instanceof Container) { layout((Container) child); } }
    }

    @Test
    public void trillionSummaryFitsAndExpansionSurvivesStatusChanges() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ResultRenderer renderer = new ResultRenderer();
            CostResult result = estimate(new WikiPrice(2_149_631_130_647L, 2_149_631_130_647L, 900L, 900L));
            renderer.showResult(result);
            renderer.getComponent().setSize(new Dimension(210, 380));
            layout(renderer.getComponent());
            List<Component> components = descendants(renderer.getComponent());
            assertTrue(components.stream().anyMatch(component -> component instanceof JLabel
                && ((JLabel) component).getText().contains("GP/XP")));
            JLabel compact = (JLabel) components.stream().filter(component -> component instanceof JLabel
                && ((JLabel) component).getText().contains("2.15T")).findFirst().get();
            assertTrue("Trillion summary clipped", compact.getFontMetrics(compact.getFont()).stringWidth("2.15T gp") <= compact.getWidth());
            JToggleButton expand = (JToggleButton) components.stream().filter(component -> component instanceof JToggleButton).findFirst().get();
            expand.doClick();
            renderer.showStatus("Loading…");
            assertSame(result, renderer.displayedResult());
            assertTrue(expand.isSelected());
            renderer.showFailure("Wiki request failed");
            assertSame(result, renderer.displayedResult());
            assertTrue(renderer.statusText().contains("previous snapshot"));
            renderer.showResult(result);
            assertTrue(expand.isSelected());
            layout(renderer.getComponent());
            // Isolated Swing fixture only: no client, game state or game input.
            BufferedImage preview = new BufferedImage(210, 380, BufferedImage.TYPE_INT_ARGB);
            Graphics2D graphics = preview.createGraphics();
            renderer.getComponent().paint(graphics);
            graphics.dispose();
            try
            {
                File directory = new File("build/reports/tests");
                assertTrue(directory.isDirectory() || directory.mkdirs());
                ImageIO.write(preview, "png", new File(directory, "sidebar-fixture.png"));
            }
            catch (java.io.IOException exception) { throw new AssertionError(exception); }
        });
    }

    @Test
    public void missingFallbackStaleAndUnknownAgeAreReadable() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ResultRenderer renderer = new ResultRenderer();
            renderer.showResult(estimate(null));
            assertEquals(CostResult.State.MISSING_QUOTES, renderer.displayedResult().getState());
            renderer.showResult(estimate(new WikiPrice(99L, null, 100L, null)));
            assertTrue(renderer.displayedResult().getNotices().stream().anyMatch(note -> note.startsWith("Opposite-side")));
            assertTrue(renderer.displayedResult().getNotices().stream().anyMatch(note -> note.startsWith("Quote older")));
            renderer.showResult(estimate(new WikiPrice(99L, 99L, null, null)));
            assertTrue(renderer.displayedResult().getNotices().stream().anyMatch(note -> note.startsWith("Quote age unknown")));
        });
    }
}

